def max_product(nums):
    """
    Finds the maximum product formed by multiplying numbers of an increasing subsequence of that array.
    """
    n = len(nums)
    dp = {}

    def solve(index, prev):
        if index == n:
            return 1

        if (index, prev) in dp:
            return dp[(index, prev)]

        ans = solve(index + 1, prev)
        if nums[index] > prev:
            ans = max(ans, nums[index] * solve(index + 1, nums[index]))

        dp[(index, prev)] = ans
        return ans

    return solve(0, float('-inf'))
```

